mapper.select:
SELECT sl.id, sl.biz_type, sl.biz_no, sl.sku_id, ps.sku_code AS sku_code, COALESCE(out_order.platform_order_no, return_order.platform_order_no) AS platform_order_no, sl.warehouse_id, w.name AS warehouse_name, sl.quantity_before, sl.quantity_change, sl.quantity_after, sl.operator_id, sl.operator_name, sl.remark, sl.created_at FROM stock_log sl LEFT JOIN product_sku ps ON sl.sku_id = ps.id AND ps.deleted = 0 LEFT JOIN warehouse w ON sl.warehouse_id = w.id AND w.deleted = 0 LEFT JOIN outbound_order oo ON sl.biz_no = oo.outbound_no AND oo.deleted = 0 LEFT JOIN sales_order out_order ON oo.order_id = out_order.id AND out_order.deleted = 0 LEFT JOIN return_order ro ON sl.biz_no = ro.return_no AND ro.deleted = 0 LEFT JOIN sales_order return_order ON ro.order_id = return_order.id AND return_order.deleted = 0
AND sl.biz_type = #{bizType}
AND sl.biz_no LIKE CONCAT('%', #{bizNo}, '%')
AND COALESCE(out_order.platform_order_no, return_order.platform_order_no) LIKE CONCAT('%', #{platformOrderNo}, '%')
AND sl.sku_id = #{skuId}
AND sl.warehouse_id = #{warehouseId}
AND sl.created_at >= #{startTime}
AND sl.created_at <= #{endTime}
ORDER BY sl.id DESC
